import React from 'react';
import './App.scss';
import data from './data';
import Suggestion from './suggestion'
class App extends React.Component {
  constructor(props)
  {
    super(props);
    this.state = {
      "id":0,
      "q_no":1,
      "que":true,
      "prev_id":null
    };
  }

  

  handleClick(new_id)
  {
    const p = this.state.id; 
    this.setState({"prev_id":p,"id":new_id,"q_no":this.state.q_no+1});
  }


  handleBack()
  {
    const p = this.state.prev_id;
    this.setState({"prev_id":null,"id":p,"q_no":this.state.q_no-1})
  }
  
  handleReset()
  {
    this.setState({"id":0,"prev_id":null})
  }

  render()
  {
    var reset;
    if (this.state.id == 0)
    {
      reset = "none"
    }
    else
    {
      reset="inline-block"
    }
    var back_avail;
    if (this.state.prev_id == null)
    {
      back_avail = "none";
    }
    else
    {
      back_avail = "inline-block";
    }
    var list_of_buttons = [];
    if (data[this.state.id].children.length > 1) {
      for ( var child_id of data[this.state.id].children)
      {
        list_of_buttons.push(
        <div>
          <button className='option' style={{margin: '4px', display:'inline-block'}} key={child_id} onClick={this.handleClick.bind(this, child_id)}>
            {data[child_id].text}
          </button>
          <br />
        </div>
       

          )
      }
        
        return (
        <div className="container"> 
          <h1 id = "question">{data[this.state.id].text}</h1>
          <hr />
          <p id= "q_no" style={{display: 'inline-block'}} >Question no. {this.state.q_no}</p>
              <div>
                {list_of_buttons}
              </div>
            <br />
            <button style={{display:back_avail, margin: '10px'}} onClick={this.handleBack.bind(this)}><i class="fas fa-arrow-left fa-2x"></i></button>
            <button style={{display:reset,float:'right', margin: '10px'}} onClick={this.handleReset.bind(this)}><i class="fas fa-undo fa-2x"></i></button>
          
        </div>
        );
    }
    else
    {
      return (
      <div>
        <Suggestion name={data[data[this.state.id].children[0]].text} />
        

      </div>
      );
    } 
  }
}

export default App;
